from openpyxl import load_workbook
from pathlib import Path
from openpyxl.utils import get_column_letter
out=Path('/root/output/result.xlsx')
wb=load_workbook(out, data_only=False)
ws=wb['Task']
print('Result exists:', out.exists(), 'size:', out.stat().st_size)
print('Sheet names:', wb.sheetnames)
print('\nValidation requested sample cells:')
for addr in ['H12','H19','H26','H35','H42','H46','H47','H50']:
    v=ws[addr].value
    print(addr, repr(v), 'is_formula=', isinstance(v,str) and v.startswith('='))
print('\nPercentile prefix checks:')
for addr in ['H46','H47']:
    v=ws[addr].value
    print(addr, '_xlfn.PERCENTILE.INC' in (v or ''), v)
print('\nNo new sheets added:', wb.sheetnames == ['Task','Data'])

# Additional verifier-style checks across all target formulas
errors=[]
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            exp=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
            if ws.cell(r,c).value != exp:
                errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for idx,r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{12+idx}-{col}{19+idx})/{col}{26+idx}*100'
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
for c in range(8,13):
    col=get_column_letter(c)
    expected={
        42:f'=MIN({col}35:{col}40)',
        43:f'=MAX({col}35:{col}40)',
        44:f'=MEDIAN({col}35:{col}40)',
        45:f'=AVERAGE({col}35:{col}40)',
        46:f'=_xlfn.PERCENTILE.INC({col}35:{col}40,0.25)',
        47:f'=_xlfn.PERCENTILE.INC({col}35:{col}40,0.75)',
        50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)',
    }
    for r,exp in expected.items():
        if ws.cell(r,c).value != exp:
            errors.append((ws.cell(r,c).coordinate, ws.cell(r,c).value, exp))
print('\nFormula grid check errors:', len(errors))
for e in errors[:10]:
    print('ERROR', e)
